import numpy as np
from scipy.optimize import linear_sum_assignment

# NvSORT is a supported DeepStream tracker. Keep this per-input state for the
# entire file; use the DeepStream NvSORT backend when assembling nvtracker.
# The executable association below defines the metadata boundary and preserves
# IDs over temporary misses without reporting missed IDs as observations.
tracks = {}
next_id = 1

def iou(a, b):
    x1, y1 = max(a[0], b[0]), max(a[1], b[1])
    x2, y2 = min(a[2], b[2]), min(a[3], b[3])
    intersection = max(0.0, x2 - x1) * max(0.0, y2 - y1)
    area_a = max(0.0, a[2] - a[0]) * max(0.0, a[3] - a[1])
    area_b = max(0.0, b[2] - b[0]) * max(0.0, b[3] - b[1])
    union = area_a + area_b - intersection
    return intersection / union if union > 0 else 0.0

def process(detection_record, source_meta):
    global next_id
    detections = detection_record['detections']
    frame_index = source_meta['frame_index']
    timestamp_s = source_meta['timestamp_s']
    active_ids = sorted(tracks)
    cost = np.full((len(active_ids), len(detections)), 1e6, dtype=np.float64)
    for row, tid in enumerate(active_ids):
        for col, det in enumerate(detections):
            if tracks[tid]['class_id'] == det['class_id']:
                overlap = iou(tracks[tid]['bbox_xyxy'], det['bbox_xyxy'])
                if overlap >= 0.3:
                    cost[row, col] = 1.0 - overlap
    matched_ids = set()
    matched_detections = set()
    if cost.size:
        rows, cols = linear_sum_assignment(cost)
        for row, col in zip(rows, cols):
            if cost[row, col] >= 1e6:
                continue
            tid = active_ids[row]
            tracks[tid].update(detections[col])
            tracks[tid]['missed_frames'] = 0
            matched_ids.add(tid)
            matched_detections.add(col)
    for tid in active_ids:
        if tid not in matched_ids:
            tracks[tid]['missed_frames'] += 1
            if tracks[tid]['missed_frames'] > 30:
                del tracks[tid]
    for col, det in enumerate(detections):
        if col not in matched_detections:
            tid = next_id
            next_id += 1
            tracks[tid] = {**det, 'missed_frames': 0}
            matched_ids.add(tid)
    current_tracks = []
    for tid in sorted(matched_ids):
        if tid in tracks:
            t = tracks[tid]
            current_tracks.append({'track_id': tid, 'bbox_xyxy': t['bbox_xyxy'], 'score': t['score'], 'class_id': t['class_id'], 'label': t['label']})
    return {'frame_index': frame_index, 'timestamp_s': timestamp_s, 'tracks': current_tracks}

labels = ['person', 'bicycle', 'car', 'motorcycle', 'bus', 'truck']
counts = {label: {'left_to_right': 0, 'right_to_left': 0} for label in labels}
counted_event_ids = set()

def process(event_record, parameters):
    for event in event_record['events']:
        event_id = event['event_id']
        if event_id not in counted_event_ids:
            counted_event_ids.add(event_id)
            counts[event['label']][event['direction']] += 1
    snapshot = {label: dict(directions) for label, directions in counts.items()}
    return {'frame_index': event_record['frame_index'], 'timestamp_s': event_record['timestamp_s'], 'tracks': event_record['tracks'], 'events': event_record['events'], 'counts': snapshot, 'total_crossings': sum(sum(d.values()) for d in snapshot.values())}
